# gen_heldout — the 100 held-out selection scenarios (D-071, option b): same
# schema as Haskins' scenarios_mixed_1000.json, generated by Nemotron with
# 3-shot examples, balanced 50/50, overlap-checked against the 1,000, and
# consistency-checked by the model at temperature 0. ONE bounded job in the
# gen venv. Needs the whole generator (about 60 GB) resident, so it launches
# only with at least HELDOUT_MIN_FREE_GB free. Result goes to Drive and is
# committed to the repo by the author's machine (data/scenarios_heldout_100.json).
import os as _os, subprocess as _sp
ARM_GEN_HELDOUT = False   # done 2026-08-30 (D-073); the set lives in Drive inputs/ and the repo
HELDOUT_MIN_FREE_GB = 75
HELDOUT_OUT = "/tmp/heldout/scenarios_heldout_100.json"
_D = MATS_ROOT + "/external/cot_obfuscation_code/defect_concealment"
_free = int(_sp.run("nvidia-smi --query-gpu=memory.free --format=csv,noheader,nounits", shell=True, capture_output=True, text=True).stdout.strip() or 0) / 1024
_gpu_mem = min(0.85, round(_free / 97.9 - 0.03, 2))
_cmd = (f"mkdir -p /tmp/heldout && {GEN_ENV_PREFIX} {GEN_PY} {MATS_ROOT}/experiments/gen_scenarios.py --source {_D}/data/scenarios_mixed_1000.json --out {HELDOUT_OUT} --n 100 --seed 2026 --gpu_mem {_gpu_mem} --max_model_len 6144 --download_dir /tmp/hf")
_alive = _sp.run("pgrep -f gen_heldout_job.py | grep -v $$ | wc -l", shell=True, capture_output=True, text=True).stdout.strip() not in ("", "0")
if _os.path.exists("/tmp/gen_heldout_job.log") and not _os.path.exists("/tmp/gen_heldout_job.done") and _alive:
    gen_heldout = {"tag": "gen_heldout_job", "log": "/tmp/gen_heldout_job.log", "done": "/tmp/gen_heldout_job.done"}; print("gen_heldout in flight")
elif not ARM_GEN_HELDOUT:
    gen_heldout = {"tag": "gen_heldout_job", "log": "/tmp/gen_heldout_job.log", "done": "/tmp/gen_heldout_job.done"}; print("not armed")
elif _os.path.exists("/tmp/gen_heldout_job.done"):
    gen_heldout = {"tag": "gen_heldout_job", "log": "/tmp/gen_heldout_job.log", "done": "/tmp/gen_heldout_job.done"}; print("gen_heldout already finished")
elif _free < HELDOUT_MIN_FREE_GB:
    gen_heldout = {"tag": "gen_heldout_job", "log": "/tmp/gen_heldout_job.log", "done": "/tmp/gen_heldout_job.done"}; print("waiting for VRAM: %.0f GB free, need %d (rerun when a training lane finishes)" % (_free, HELDOUT_MIN_FREE_GB))
else:
    gen_heldout = bg_run("import subprocess, sys\nsys.path.insert(0, %r)\nfrom notebook_helpers import dput_atomic\nr = subprocess.run(%r + ' > /tmp/gen_heldout_vllm.log 2>&1', shell=True)\nprint('rc', r.returncode)\nimport os\nif os.path.exists(%r):\n    dput_atomic(%r, %r); dput_atomic(%r, %r); print('uploaded')\n" % (MATS_ROOT, _cmd, HELDOUT_OUT, HELDOUT_OUT, CORPUS_DRIVE + "/scenarios_heldout_100.json", HELDOUT_OUT.replace(".json", ".meta.json"), CORPUS_DRIVE + "/scenarios_heldout_100.meta.json"), tag="gen_heldout_job")
    print("launched", gen_heldout, "| gpu_mem %.2f with %.0f GB free" % (_gpu_mem, _free))
